'use strict';

const fs = require('node:fs');

class StoreError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'StoreError';
  }
}

function describeProblem(todo, seenIds) {
  if (todo === null || typeof todo !== 'object' || Array.isArray(todo)) {
    return 'is not an object';
  }
  if (!Number.isSafeInteger(todo.id) || todo.id < 1) {
    return 'has an invalid "id" (expected a positive integer)';
  }
  if (seenIds.has(todo.id)) {
    return `has a duplicate "id" ${todo.id}`;
  }
  if (typeof todo.text !== 'string' || todo.text.trim() === '') {
    return 'has an invalid "text" (expected a non-empty string)';
  }
  if (typeof todo.completed !== 'boolean') {
    return 'has an invalid "completed" (expected true or false)';
  }
  if (typeof todo.createdAt !== 'string' || Number.isNaN(Date.parse(todo.createdAt))) {
    return 'has an invalid "createdAt" (expected an ISO timestamp)';
  }
  return null;
}

function validateTodos(data, filePath) {
  if (!Array.isArray(data)) {
    throw new StoreError(`${filePath} is corrupted: expected a JSON array of todos.`);
  }
  const seenIds = new Set();
  data.forEach((todo, index) => {
    const problem = describeProblem(todo, seenIds);
    if (problem) {
      throw new StoreError(`${filePath} is corrupted: todo at index ${index} ${problem}.`);
    }
    seenIds.add(todo.id);
  });
}

/**
 * Reads and validates the todo list. A missing file is an empty list; any
 * other read failure, invalid JSON or malformed todo throws StoreError so the
 * caller never overwrites data it could not understand.
 */
function loadTodos(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      return [];
    }
    throw new StoreError(`Could not read ${filePath}: ${err.message}`, { cause: err });
  }

  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    throw new StoreError(
      `${filePath} is corrupted: invalid JSON (${err.message}). Fix or remove the file.`,
      { cause: err },
    );
  }
  validateTodos(data, filePath);
  return data;
}

/**
 * Writes to a temp file and renames it into place, so an interrupted write
 * leaves the previous file intact instead of a truncated one.
 */
function saveTodos(filePath, todos) {
  const tmpPath = `${filePath}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tmpPath, `${JSON.stringify(todos, null, 2)}\n`);
    fs.renameSync(tmpPath, filePath);
  } catch (err) {
    fs.rmSync(tmpPath, { force: true });
    throw new StoreError(`Could not write ${filePath}: ${err.message}`, { cause: err });
  }
}

module.exports = { StoreError, loadTodos, saveTodos };

