#!/usr/bin/env node
'use strict';

const path = require('node:path');
const {
  TodoError,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatTodo,
  formatList,
} = require('./lib/todos');
const { StoreError, loadTodos, saveTodos } = require('./lib/store');

const DATA_FILE = 'todos.json';

const USAGE = `Usage:
  node index.js add "<text>"     Add a new todo
  node index.js list             List all todos
  node index.js complete <id>    Mark a todo as done
  node index.js delete <id>      Delete a todo
  node index.js help             Show this help`;

const HELP_FLAGS = new Set(['help', '--help', '-h']);

function requireSingleId(args, usage) {
  if (args.length === 0) {
    throw new TodoError(`Missing todo id. Usage: ${usage}`);
  }
  if (args.length > 1) {
    throw new TodoError(`Expected exactly one todo id. Usage: ${usage}`);
  }
  return parseId(args[0]);
}

// Arguments are validated before the data file is read, so bad input is
// reported the same way whatever state todos.json is in.
const COMMANDS = new Map([
  ['add', (args, { filePath, out }) => {
    if (args.length === 0) {
      throw new TodoError('Missing todo text. Usage: node index.js add "<text>"');
    }
    // Unquoted words (`add Buy milk`) are joined so they are not silently dropped.
    const text = args.join(' ');
    const { todos, todo } = addTodo(loadTodos(filePath), text);
    saveTodos(filePath, todos);
    out(`Added todo #${todo.id}: ${todo.text}`);
  }],
  ['list', (args, { filePath, out }) => {
    if (args.length > 0) {
      throw new TodoError('The list command takes no arguments. Usage: node index.js list');
    }
    out(formatList(loadTodos(filePath)));
  }],
  ['complete', (args, { filePath, out }) => {
    const id = requireSingleId(args, 'node index.js complete <id>');
    const { todos, todo, alreadyCompleted } = completeTodo(loadTodos(filePath), id);
    if (alreadyCompleted) {
      out(`Todo #${todo.id} is already done: ${todo.text}`);
      return;
    }
    saveTodos(filePath, todos);
    out(`Completed: ${formatTodo(todo)}`);
  }],
  ['delete', (args, { filePath, out }) => {
    const id = requireSingleId(args, 'node index.js delete <id>');
    const { todos, todo } = deleteTodo(loadTodos(filePath), id);
    saveTodos(filePath, todos);
    out(`Deleted todo #${todo.id}: ${todo.text}`);
  }],
]);

/**
 * Runs one CLI invocation and returns the process exit code: 0 on success,
 * 1 on a usage, validation or storage error (reported on stderr). Unexpected
 * errors are re-thrown so they surface with a stack trace.
 */
function run(argv, { cwd = process.cwd(), stdout = process.stdout, stderr = process.stderr } = {}) {
  const [command, ...args] = argv;
  if (command === undefined) {
    stderr.write(`${USAGE}\n`);
    return 1;
  }
  if (HELP_FLAGS.has(command)) {
    stdout.write(`${USAGE}\n`);
    return 0;
  }
  const handler = COMMANDS.get(command);
  if (!handler) {
    stderr.write(`Error: Unknown command "${command}".\n${USAGE}\n`);
    return 1;
  }

  const context = {
    filePath: path.join(cwd, DATA_FILE),
    out: (line) => stdout.write(`${line}\n`),
  };
  try {
    handler(args, context);
    return 0;
  } catch (err) {
    if (err instanceof TodoError || err instanceof StoreError) {
      stderr.write(`Error: ${err.message}\n`);
      return 1;
    }
    throw err;
  }
}

if (require.main === module) {
  process.exitCode = run(process.argv.slice(2));
}

module.exports = { run, DATA_FILE };

