'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  TodoError,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
} = require('../lib/todos');

const NOW = new Date('2026-01-02T03:04:05.678Z');

function todo(id, overrides = {}) {
  return { id, text: `Todo ${id}`, completed: false, createdAt: NOW.toISOString(), ...overrides };
}

describe('parseId', () => {
  for (const [input, expected] of [['1', 1], ['42', 42], [' 7 ', 7], ['007', 7]]) {
    it(`accepts ${JSON.stringify(input)} as ${expected}`, () => {
      assert.equal(parseId(input), expected);
    });
  }

  const invalid = ['', '   ', 'abc', '0', '-1', '1.5', '1e3', '0x1', '12abc', 'Infinity', '١', '9007199254740993'];
  for (const input of invalid) {
    it(`rejects ${JSON.stringify(input)}`, () => {
      assert.throws(() => parseId(input), { name: 'TodoError', message: /Invalid todo id/ });
    });
  }
});

describe('addTodo', () => {
  it('creates the first todo with id 1, pending status and an ISO createdAt', () => {
    const { todos, todo: added } = addTodo([], 'Buy groceries', NOW);
    assert.deepEqual(added, {
      id: 1,
      text: 'Buy groceries',
      completed: false,
      createdAt: '2026-01-02T03:04:05.678Z',
    });
    assert.deepEqual(todos, [added]);
  });

  it('assigns max existing id + 1 so ids are not reused after a gap', () => {
    const { todo: added } = addTodo([todo(1), todo(5), todo(3)], 'Next', NOW);
    assert.equal(added.id, 6);
  });

  it('trims surrounding whitespace and keeps unicode text intact', () => {
    const { todo: added } = addTodo([], '  Café ☕ 日本語 🍕  ', NOW);
    assert.equal(added.text, 'Café ☕ 日本語 🍕');
  });

  for (const text of ['', '   ', '\t\n', undefined, null, 42]) {
    it(`rejects ${JSON.stringify(text) ?? 'undefined'} text`, () => {
      assert.throws(() => addTodo([], text, NOW), { name: 'TodoError', message: /cannot be empty/ });
    });
  }

  it('does not mutate the input list', () => {
    const input = [todo(1)];
    const snapshot = structuredClone(input);
    addTodo(input, 'Another', NOW);
    assert.deepEqual(input, snapshot);
  });
});

describe('completeTodo', () => {
  it('marks only the matching todo as completed', () => {
    const { todos, todo: done, alreadyCompleted } = completeTodo([todo(1), todo(2)], 2);
    assert.equal(alreadyCompleted, false);
    assert.equal(done.completed, true);
    assert.deepEqual(todos, [todo(1), todo(2, { completed: true })]);
  });

  it('reports an already-completed todo without changing the list', () => {
    const input = [todo(1, { completed: true })];
    const result = completeTodo(input, 1);
    assert.equal(result.alreadyCompleted, true);
    assert.equal(result.todos, input);
  });

  it('throws TodoError for an id that does not exist', () => {
    assert.throws(() => completeTodo([todo(1)], 99), { name: 'TodoError', message: 'Todo #99 not found.' });
    assert.throws(() => completeTodo([], 1), TodoError);
  });

  it('does not mutate the input list or todo', () => {
    const input = [todo(1)];
    const snapshot = structuredClone(input);
    completeTodo(input, 1);
    assert.deepEqual(input, snapshot);
  });
});

describe('deleteTodo', () => {
  it('removes only the matching todo and returns it', () => {
    const { todos, todo: removed } = deleteTodo([todo(1), todo(2), todo(3)], 2);
    assert.deepEqual(removed, todo(2));
    assert.deepEqual(todos.map((t) => t.id), [1, 3]);
  });

  it('throws TodoError for an id that does not exist', () => {
    assert.throws(() => deleteTodo([todo(1)], 2), { name: 'TodoError', message: 'Todo #2 not found.' });
    assert.throws(() => deleteTodo([], 1), TodoError);
  });

  it('does not mutate the input list', () => {
    const input = [todo(1), todo(2)];
    const snapshot = structuredClone(input);
    deleteTodo(input, 1);
    assert.deepEqual(input, snapshot);
  });
});

describe('formatList', () => {
  it('shows a hint when there are no todos', () => {
    assert.match(formatList([]), /^No todos yet/);
  });

  it('shows id, status indicator and text on one line per todo, in stored order', () => {
    const output = formatList([todo(2, { text: 'Walk the dog', completed: true }), todo(1, { text: 'Buy milk' })]);
    assert.equal(output, '2. [x] Walk the dog\n1. [ ] Buy milk');
  });
});

