    assert.deepEqual(removed, todo(2));
    assert.deepEqual(todos.map((t) => t.id), [1, 3]);
  });

  it('throws TodoError for an id that does not exist', () => {
    assert.throws(() => deleteTodo([todo(1)], 2), { name: 'TodoError', message: 'Todo #2 not found.' });
    assert.throws(() => deleteTodo([], 1), TodoError);
  });

  it('does not mutate the input list', () => {
    const input = [todo(1), todo(2)];
    const snapshot = structuredClone(input);
    deleteTodo(input, 1);
    assert.deepEqual(input, snapshot);
  });
});

describe('formatList', () => {
  it('shows a hint when there are no todos', () => {
    assert.match(formatList([]), /^No todos yet/);
  });

  it('shows id, status indicator and text on one line per todo, in stored order', () => {
    const output = formatList([todo(2, { text: 'Walk the dog', completed: true }), todo(1, { text: 'Buy milk' })]);
    assert.equal(output, '2. [x] Walk the dog\n1. [ ] Buy milk');
  });
});

