  // but atomic writes must keep the file valid and the temp files distinct.
  it('leaves a valid data file and no temp files when adds run concurrently', async () => {
    const execFileAsync = promisify(execFile);
    const runs = Array.from({ length: 8 }, (_, i) =>
      execFileAsync(process.execPath, [ENTRY, 'add', `Task ${i}`], { cwd: dir, timeout: CHILD_TIMEOUT_MS }));
    await Promise.all(runs);

    const todos = readTodos();
    assert.ok(todos.length >= 1 && todos.length <= 8);
    assert.deepEqual(fs.readdirSync(dir), ['todos.json']);
    assert.equal(node('list').code, 0);
  });
});

